    if (k < 0.5) { sq = vec2(0.5, f - 0.5); nsq = vec2(1.0, 0.0); }
    else if (k < 1.5) { sq = vec2(0.5 - f, 0.5); nsq = vec2(0.0, 1.0); }
    else if (k < 2.5) { sq = vec2(-0.5, 0.5 - f); nsq = vec2(-1.0, 0.0); }
    else { sq = vec2(f - 0.5, -0.5); nsq = vec2(0.0, -1.0); }
