    if (em < 1.5) g = 0.8 + 0.1 * sin(uT * 0.5 + position.z * 650. + position.x * 410. + position.y * 300.);
    else if (em < 2.5) g = 0.72 + 0.22 * sin(position.z * 300. + position.x * 200. - uT * 0.8);
    else if (em < 3.5) g = 0.45 + 0.55 * (0.5 + 0.5 * sin(uT * 1.2 + aA.z));
    else if (em < 4.5) g = 0.8 + 1.1 * uThrust;
